"""Research-only transport reminder; frozen synthetic request and parser boundaries."""
import ast
import json
from pathlib import Path

import pytest

from test_explain import offline, runner, invoke, payload
from reference.factories import explain
from reference.inputs import ROOT, canonical, read, sha
from reference.providers import Bedrock, Fixture
from reference.runtime import Runner, model_response_json, report


def test_only_research_gains_a_block_against_frozen_base_requests(tmp_path):
    # Generated by the real guarded fixture graph BEFORE the wrapper edit at this commit.
    baseline = read(ROOT/'tests/fixtures/explain-request-baseline.json')
    run = runner(tmp_path)
    invoke(run)
    assert set(baseline['request_sha256']) == set(explain.ROLES)
    for role in explain.ROLES:
        request = read(tmp_path/'requests'/f'{role}.json')
        assert sha(canonical(payload(request))) == baseline['declared_sha256'][role]
        if role == 'explain_research':
            content = request['messages'][0]['content']
            assert len(content) == 2
            assert sha(content[0]['text'].encode()) == baseline['research_first_block_sha256']
            request['messages'][0]['content'] = content[:1]
        assert sha(canonical(request)) == baseline['request_sha256'][role]
    definitions = {node.name: sha(ast.dump(node).encode())
                   for node in ast.parse(Path(explain.__file__).read_text()).body
                   if isinstance(node, ast.FunctionDef) and node.name != 'request'}
    assert definitions == baseline['unchanged_definitions_sha256']


@pytest.mark.parametrize('supplied', [False, True])
def test_final_contract_follows_intact_data_and_reaches_transport(tmp_path, supplied):
    run = runner(tmp_path)
    if not supplied:
        run.bundle['declared'].pop('research', None)
    declared = explain.declared(run, 'explain_research')
    request = explain.request(run, 'explain_research', declared, [], [], True)
    content = request['messages'][0]['content']
    assert len(request['messages']) == 1 and request['messages'][0]['role'] == 'user'
    assert payload(request) == declared
    assert declared['supplied_research']['supplied'] is supplied
    assert declared['supplied_research']['fresh_web_research'] is False
    contract = content[-1]['text']
    assert contract.startswith('Final research response contract:\n')
    assert all('Final research response contract:' not in block['text'] for block in content[:-1])
    assert 'first non-whitespace character must be {' in contract and 'last must be }' in contract
    assert 'object-valued artifact field' in contract
    assert 'No preamble, postscript, Markdown fences, multiple objects' in contract
    illustration = contract.split('Syntax-only envelope illustration:\n')[1].split('\n')[0]
    assert json.loads(illustration) == {'artifact': {}}
    assert explain.parse('explain_research', illustration) == {'artifact': {}}
    assert 'not substitute curriculum or permission to omit required native fields' in contract
    assert 'do not return an empty or template response' in contract
    # Exercise the actual provider forwarding with an in-memory client, no SDK or network.
    calls = []
    class Client:
        def converse(self, **kwargs):
            calls.append(kwargs)
            return {'synthetic_transport_only': True}
    provider = Bedrock({'model': 'synthetic-no-service', 'max_output_tokens': 100})
    provider.client = Client()
    provider.invoke(request, role='explain_research', notes_pages=None)
    assert calls[0]['messages'] is request['messages']
    assert calls[0]['messages'][0]['content'][-1]['text'] == contract


ENVELOPE = '{"artifact":{"topic":"SYNTHETIC","no_real_misconceptions":true,"candidates":[],"notes":"No fresh research"}}'


@pytest.mark.parametrize('text', [
    '### Step 1: Understand the Task and Guidelines\n'+ENVELOPE,
    'Procedure commentary\n```json\n'+ENVELOPE+'\n```',
    '```json\n'+ENVELOPE+'\n```\n```json\n'+ENVELOPE+'\n```',
    ENVELOPE+'\n'+ENVELOPE,
    '{"artifact":{"candidates":[],}}',
    json.dumps(json.loads(ENVELOPE)['artifact']),
    '{"written":true,"file":"research.json"}',
    '{"artifact":"file-write receipt"}',
])
def test_invalid_research_stays_failed_raw_and_unrepeated(tmp_path, monkeypatch, text):
    def invalid(self, request, *, role, notes_pages):
        assert role == 'explain_research'
        return {'output': {'message': {'content': [{'text': text}]}}, 'stopReason': 'end_turn'}
    monkeypatch.setattr(Fixture, 'invoke', invalid)
    run = runner(tmp_path)
    with pytest.raises(ValueError, match='required stage unavailable'):
        invoke(run)
    assert run.result('explain_research')['status'] == 'failed'
    assert read(tmp_path/'responses/explain_research.json')['output']['message']['content'][0]['text'] == text
    assert not (tmp_path/'artifacts/research.json').exists()
    assert report(tmp_path, explain)['status'] == 'partial_or_failed'
    before = read(tmp_path/'synthetic-ledger.json')
    with pytest.raises(ValueError, match='required stage unavailable'):
        invoke(Runner(tmp_path, explain, resume=True))
    assert read(tmp_path/'synthetic-ledger.json') == before
    assert len(before['calls']) == 1


def test_existing_whole_fence_and_imperfect_artifact_rules_are_unchanged():
    # Requesting strict JSON does not narrow the already accepted T04 framing or native keys.
    text, framing = model_response_json('```json\n'+ENVELOPE+'\n```')
    assert framing == 'markdown_json_fence'
    assert explain.parse('explain_research', text) == json.loads(ENVELOPE)
    value = {'artifact': {'unknown_native_field': 'preserved'}, 'extra_audit': ['negative finding']}
    assert explain.parse('explain_research', json.dumps(value)) == value
